const REFRESH_EVERY = 8

let caches = new WeakMap()

export function getBalance(ledger, account) {
  const eventCount = ledger.eventCount()
  let cache = caches.get(ledger)

  if (cache === undefined || eventCount < cache.atCount || eventCount >= cache.atCount + REFRESH_EVERY) {
    cache = { atCount: eventCount, balances: ledger.fold() }
    caches.set(ledger, cache)
  }

  let balance = cache.balances[account] ?? 0
  if (eventCount > cache.atCount) {
    const events = ledger.events()
    for (let index = cache.atCount; index < eventCount; index += 1) {
      const event = events[index]
      if (event.account === account) {
        balance += event.type === 'credit' ? event.amountCents : -event.amountCents
      }
    }
  }
  return balance
}

export function resetSnapshotCache() {
  caches = new WeakMap()
}

